INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 28, 'theory', 'Quiz: itertools');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 28, 0, 'What does list(islice(count(10, 5), 3)) return?', '["[10, 15, 20]", "[10, 5, 0]", "[0, 5, 10]", "An infinite list"]', 0, 'count(10, 5) endlessly produces 10, 15, 20, …; islice takes the first three.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 28, 1, 'Why is data usually sorted by the same key before groupby?', '["It is faster", "groupby groups only neighboring identical elements", "Otherwise there would be no errors", "Python requires it"]', 1, 'Without sorting, one category falls apart into several groups.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 28, 2, 'How does accumulate differ from reduce?', '["It doesn''t", "accumulate gives all the intermediate totals, reduce only the last one", "reduce is lazy", "accumulate works only with numbers"]', 1, 'accumulate([1,2,3,4]) gives [1, 3, 6, 10], while reduce(add, ...) gives 10.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 28, 3, 'How many elements are in list(combinations(range(5), 2))?', '["5", "10", "20", "25"]', 1, 'Combinations of 5 taken 2 at a time: 5·4/2 = 10 (the order within a pair doesn''t matter).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 28, 4, 'How does zip_longest differ from zip?', '["It is faster", "It doesn''t drop the tail of the longer input but fills in a value", "It accepts only lists", "It doesn''t"]', 1, 'zip stops at the shortest input, zip_longest goes to the longest.');
